#[cfg(unix)]
fn write_key(fd: RawFd, key: &[u8; KEY_LEN]) -> std::io::Result<()> {
    // Ensure exactly 0600 (owner read/write, nothing for group/other)
    // before any secret byte is written.
    //
    // The umask applied at open() may have stripped the owner bits (e.g.
    // umask 0777 yields mode 0000), and some filesystems fail to record the
    // requested mode. fchmod on our fresh fd restores the full mode (it is
    // not affected by umask and can never grant group/other access), then
    // fstat confirms the on-disk mode is exactly 0600 -- fchmod can appear
    // to succeed on filesystems that silently ignore it (e.g. certain FAT
    // mounts), so the result must be verified. If either step fails, no key
